SELECT s.point_code AS point_code, s.score AS score FROM progress_score s WHERE s.learner = :learner AND s.subject_id = CAST(:subject_id AS INTEGER) AND s.id = (SELECT MAX(m.id) FROM progress_score m WHERE m.learner = s.learner AND m.point_code = s.point_code AND m.subject_id = s.subject_id) AND s.score < CAST(:below AS INTEGER) ORDER BY s.score ASC, s.point_code ASC LIMIT CAST(:limit AS INTEGER)
